    static Mono<?> invoke(Object target,String method,Object argument){try{return (Mono<?>)Arrays.stream(target.getClass().getMethods()).filter(m->m.getName().equals(method)&&m.getParameterCount()==1).findFirst().orElseThrow().invoke(target,argument);}catch(InvocationTargetException e){return Mono.error(e.getCause());}catch(Exception e){throw new AssertionError(e);}}
