    static final class Harness {
        final Driver driver=new Driver();final Clock clock=Clock.fixed(NOW,ZoneOffset.UTC);final AtomicLong nanos=new AtomicLong(),ids=new AtomicLong(100);final LongSupplier monotonic=nanos::get;final AtomicInteger policyCalls=new AtomicInteger(),principalCalls=new AtomicInteger();
        SecurityPrincipal actor=principal("maker");boolean permit=true,nativeAvailable=true,sourceAvailable,replaceContextClient;Integer sourceScale;int sourceCalls,denyPolicyAt,finalPolicyCall=3;long finalSourceMillis=500,finalPolicyAdvance;long nativeMillis=1000;RuntimeException nativeFailure;
        final OwnedLeaseConnectionFactory factory=new OwnedLeaseConnectionFactory(driver);final DatabaseClient client=DatabaseClient.create(factory);final R2dbcEntityTemplate template=new R2dbcEntityTemplate(client,PostgresDialect.INSTANCE);final R2dbcTransactionManager manager=new R2dbcTransactionManager(factory);
        Object service(boolean enabled){
            var nativeType=type(CORE+"InsuranceReferenceNativeContext");
            Object context=Proxy.newProxyInstance(nativeType.getClassLoader(),new Class[]{nativeType},(p,m,a)->switch(m.getName()){
                case "databaseClient"->replaceContextClient?DatabaseClient.create(new OwnedLeaseConnectionFactory(new Driver())):client;
                case "begin"->{if(!nativeAvailable)yield Mono.error(new IllegalStateException("NATIVE_UNAVAILABLE"));if(nativeFailure!=null)yield Mono.error(nativeFailure);Object request=a[0];yield Mono.just(construct(CORE+"InsuranceReferenceNativeContext$Stamp",get(request,"nonce"),get(request,"recordId"),get(request,"kind"),NOW.toEpochMilli(),NOW,NOW.plusMillis(nativeMillis)));}
                case "complete"->Mono.just(true);case "toString"->"ControlledNativeContextTestOnly";default->throw new UnsupportedOperationException(m.getName());});
            var session=construct(CORE+"InsuranceReferencePersistence$Session",template,manager,context);var persistence=construct(CORE+"InsuranceReferencePersistence",session,session,clock,monotonic);
            SecurityContextPort principals=()->{principalCalls.incrementAndGet();return Mono.justOrEmpty(actor);};
            PolicyDecisionPort policies=(p,action,resource,details)->{int call=policyCalls.incrementAndGet();if(call==finalPolicyCall&&finalPolicyAdvance!=0)nanos.addAndGet(finalPolicyAdvance);return Mono.just(permit&&call!=denyPolicyAt?Decision.permit():Decision.deny("controlled"));};
            var sourceType=type(CORE+"InsuranceReferenceSourceVerifier");Object source=Proxy.newProxyInstance(sourceType.getClassLoader(),new Class[]{sourceType},(p,m,a)->{if(!sourceAvailable)return Mono.error(new IllegalStateException("SOURCE_OWNER_UNAVAILABLE"));var revision=(InsuranceReferenceContracts.Revision)a[0];var tax=revision.definition() instanceof InsuranceReferenceContracts.PremiumTax value?value:null;return Mono.just(construct(CORE+"InsuranceReferenceSourceVerifier$Evidence",InsuranceReferenceCodec.digest(revision),tax==null?null:tax.currencyPolicy(),tax==null?null:sourceScale==null?tax.postedScale():sourceScale,NOW,NOW.plusMillis(++sourceCalls>=2?finalSourceMillis:500)));});
            return construct(CORE+"impl.InsuranceReferencePublicationServiceImpl",enabled,principals,policies,Set.of("https://synthetic.invalid"),persistence,source,clock,monotonic,(Supplier<UUID>)()->new UUID(1,ids.incrementAndGet()));
        }
    }
