    record Governed(UUID intent,UUID approval,String digest,InsuranceReferenceContracts.Revision proposed,String canonical) {}
    static Object row(String name,Object... values){return construct("io.fireflysoftware.masters.models.entities.insurance.reference.InsuranceReferenceRows$"+name,values);}
    static void seed(Harness h,Object row,int copies) {
        try {var table=row.getClass().getAnnotation(org.springframework.data.relational.core.mapping.Table.class).value();var values=new LinkedHashMap<String,Object>();
            for(var field:row.getClass().getRecordComponents()){String column=row.getClass().getDeclaredField(field.getName()).getAnnotation(org.springframework.data.relational.core.mapping.Column.class).value();Object value=field.getAccessor().invoke(row);values.put(column,value instanceof Enum<?> e?e.name():value);}
            var queue=h.driver.answers.computeIfAbsent(table,k->new ArrayDeque<>());for(int i=0;i<copies;i++)queue.add(new LinkedHashMap<>(values));
        }catch(Exception e){throw new AssertionError(e);}
    }
    static Governed governed(Harness h,String operation,boolean current,boolean expired,boolean tax) {
        var proto=tax?(InsuranceReferenceContracts.Revision)InsuranceReferenceCodecTest.decode(InsuranceReferenceCodecTest.fixture("PREMIUM_TAX").toString()):definition();
        UUID intent=new UUID(1,201),approval=new UUID(1,202),oldPublication=new UUID(1,203),nextPublication=new UUID(1,204);
        var expected=new io.fireflysoftware.masters.interfaces.dtos.insurance.reference.InsuranceReferenceCommands.Head(current?oldPublication:null,current?1:0,0);
        var proposed=new InsuranceReferenceContracts.Revision(proto.kind(),RECORD,operation.equals("WITHDRAW")?oldPublication:nextPublication,operation.equals("WITHDRAW")?1:current?2:1,proto.code(),proto.effectiveFrom(),proto.effectiveUntil(),proto.definition(),proto.provenance());
        var value=new InsuranceReferenceIntentCodec.Intent(operation,proposed,expected);String canonical=InsuranceReferenceIntentCodec.encode(value),digest=InsuranceReferenceIntentCodec.digest(canonical);
        seed(h,row("Identity","GLOBAL_MASTER",RECORD,proto.kind(),proto.code()),6);
        if(current){seed(h,row("ReferenceControl","GLOBAL_MASTER",RECORD,proto.kind(),oldPublication,1L,0L,"ACTIVE"),6);var prior=new InsuranceReferenceContracts.Revision(proto.kind(),RECORD,oldPublication,1,proto.code(),proto.effectiveFrom(),proto.effectiveUntil(),proto.definition(),proto.provenance());seed(h,row("Revision","GLOBAL_MASTER",oldPublication,RECORD,proto.kind(),1L,InsuranceReferenceCodec.encode(prior),InsuranceReferenceCodec.digest(prior),prior.effectiveFrom(),prior.effectiveUntil(),new UUID(1,205),NOW.minusSeconds(15)),6);}
        seed(h,row("MakerIntent","GLOBAL_MASTER",intent,RECORD,proto.kind(),operation,canonical,digest,expected.publicationId(),expected.revision(),expected.generation(),"https://synthetic.invalid","maker",NOW.plusSeconds(3600),NOW.minusSeconds(10)),6);
        seed(h,row("IntentControl","GLOBAL_MASTER",intent,RECORD,proto.kind(),1L,"APPROVED",approval,null),6);
        seed(h,row("CheckerApproval","GLOBAL_MASTER",approval,RECORD,proto.kind(),intent,digest,0L,"https://synthetic.invalid","checker",expired?NOW.minusSeconds(1):NOW.plusSeconds(300),NOW.minusSeconds(5)),6);
        return new Governed(intent,approval,digest,proposed,canonical);
    }
    static Object intentAction(Governed g,long generation){return construct(CMD+"IntentAction",ACTION,RECORD,g.proposed().kind(),g.intent(),g.digest(),generation);}
